-- NOIR user-owned cloud data schema
create extension if not exists pgcrypto;
create table if not exists public.characters(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,is_public boolean not null default false,data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.personas(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.lorebooks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,character_id text,title text not null,data jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('user','assistant')),content text not null,created_at timestamptz not null default now());
alter table public.characters enable row level security; alter table public.personas enable row level security; alter table public.lorebooks enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security;
create policy "characters read" on public.characters for select using(is_public or auth.uid()=user_id); create policy "characters own" on public.characters for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "personas own" on public.personas for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "lorebooks own" on public.lorebooks for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "conversations own" on public.conversations for all using(auth.uid()=user_id) with check(auth.uid()=user_id); create policy "messages own" on public.messages for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
